export const translations = Object.fromEntries(rows.trim().split('\n').map(row => { const [ru, en, uk] = row.split('|'); return [ru, { en, uk }]; }));
const side = (value, locale) => locale === 'en' ? value === 'Белые' ? 'White' : 'Black' : value === 'Белые' ? 'Білі' : 'Чорні';
export const patterns = [
  [/^(\d+): (Забит|На столе)$/, (m,l) => m[1]+': '+(l==='en'?(m[2]==='Забит'?'Pocketed':'On the table'):(m[2]==='Забит'?'Забито':'На столі'))],
  [/^(\d+) × (\d+) · (\d+) мин \+ 5 сек$/, (m,l) => `${m[1]} × ${m[2]} · ${m[3]} ${l === 'en' ? 'min + 5 sec' : 'хв + 5 с'}`],
  [/^Шашка (\d+)$/, (m,l) => `${l === 'en' ? 'Piece' : 'Шашка'} ${m[1]}`],
  [/^(Два игрока, одно устройство|Комната [A-F0-9]{12}|Пригласите друга за доску) · Раунд (\d+) · (\d+):(\d+)$/, (m,l) => {
    const prefix = m[1].startsWith('Комната ') ? (l === 'en' ? 'Room ' : 'Кімната ') + m[1].slice(8) : translations[m[1]][l];
    return `${prefix} · ${l === 'en' ? 'Round' : 'Раунд'} ${m[2]} · ${m[3]}:${m[4]}`;
  }],
  [/^Раунд (\d+) · Счёт (\d+):(\d+) \(белые : чёрные\)$/, (m,l) => l === 'en' ? `Round ${m[1]} · Score ${m[2]}:${m[3]} (White : Black)` : `Раунд ${m[1]} · Рахунок ${m[2]}:${m[3]} (білі : чорні)`],
  [/^Раунд (\d+): ничья$/, (m,l) => l === 'en' ? `Round ${m[1]}: draw` : `Раунд ${m[1]}: нічия`],
  [/^(Белые|Чёрные) выиграли раунд (\d+)!$/, (m,l) => l === 'en' ? `${side(m[1],l)} win round ${m[2]}!` : `${side(m[1],l)} виграли раунд ${m[2]}!`],
  [/^(Белые|Чёрные) продвигаются на одну клетку вперёд\. Обе стороны снова получают по восемь шашек\.$/, (m,l) => `${side(m[1],l)} ${l === 'en' ? 'advance one square. Both sides receive eight pieces again.' : 'просуваються на одну клітинку вперед. Обидві сторони знову отримують по вісім шашок.'}`],
  [/^Ряды стоят вплотную\. (Белые|Чёрные) отступают на одну клетку\. Обе стороны снова получают по восемь шашек\.$/, (m,l) => l === 'en' ? `Rows are adjacent. ${side(m[1],l)} retreat one square. Both sides receive eight pieces again.` : `Ряди стоять впритул. ${side(m[1],l)} відступають на одну клітинку. Обидві сторони знову отримують по вісім шашок.`],
  [/^(Белые|Чёрные) больше не могут отступить: край доски\. Партия завершена!$/, (m,l) => `${side(m[1],l)} ${l === 'en' ? 'cannot retreat beyond the board edge. Game over!' : 'більше не можуть відступити: край дошки. Партію завершено!'}`],
  [/^(Белые|Чёрные) потеряли все шашки\. Отличный раунд!$/, (m,l) => `${side(m[1],l)} ${l === 'en' ? 'lost all their pieces. Great round!' : 'втратили всі шашки. Чудовий раунд!'}`],
  [/^(Следующий раунд начнётся, когда оба игрока будут готовы\. )?Очередь сохраняется: следующий удар у (белых|чёрных)\.$/, (m,l) => (m[1] ? l === 'en' ? 'The next round starts when both players are ready. ' : 'Наступний раунд почнеться, коли обидва гравці будуть готові. ' : '') + (l === 'en' ? `Turn order is preserved: ${m[2] === 'белых' ? 'White' : 'Black'} shoot next.` : `Черга зберігається: наступний удар у ${m[2] === 'белых' ? 'білих' : 'чорних'}.`)],
  [/^(\d+) × (\d+) · Без таймера$/, (m, l) => `${m[1]} × ${m[2]} · ${l === 'en' ? 'No timer' : 'Без таймера'}`],
  [/^(\d+) (полуходов|удар|удара|ударов)$/, (m, l) => `${m[1]} ${l === 'en' ? m[2] === 'полуходов' ? 'plies' : 'shots' : m[2] === 'полуходов' ? 'півходів' : 'ударів'}`],
  [/^Комната ([A-F0-9]{12})(.*)$/, (m, l) => `${l === 'en' ? 'Room' : 'Кімната'} ${m[1]}${m[2]}`],
  [/^(Белые|Чёрные) · (В игре|Не в сети)$/, (m, l) => `${side(m[1], l)} · ${l === 'en' ? m[2] === 'В игре' ? 'Online' : 'Offline' : m[2] === 'В игре' ? 'У грі' : 'Не в мережі'}`],
  [/^(Белые|Чёрные), согласны на ничью\?$/, (m, l) => `${side(m[1], l)}, ${l === 'en' ? 'accept a draw?' : 'згодні на нічию?'}`],
  [/^(Белые|Чёрные) предлагают завершить партию вничью\. Передайте решение сопернику\.$/, (m, l) => `${side(m[1], l)} ${l === 'en' ? 'offer a draw. Let the opponent decide.' : 'пропонують нічию. Передайте рішення супернику.'}`],
  [/^(Белые|Чёрные) сдались\. Победа за (белыми|чёрными)\.$/, (m, l) => l === 'en' ? `${side(m[1], l)} resigned. ${m[2] === 'белыми' ? 'White' : 'Black'} wins.` : `${side(m[1], l)} здалися. Перемога за ${m[2] === 'белыми' ? 'білими' : 'чорними'}.`],
  [/^(Белые|Чёрные) остались без доступных ходов\.$/, (m, l) => `${side(m[1], l)} ${l === 'en' ? 'have no legal moves left.' : 'залишилися без доступних ходів.'}`],
  [/^Шашечная доска (\d+) на (\d+)$/, (m, l) => `${l === 'en' ? 'Draughts board' : 'Шашкова дошка'} ${m[1]} × ${m[2]}`],
  [/^([a-l]\d+), (Белые|Чёрные), (пешка|конь|слон|ладья|ферзь|король|дамка|шашка)(, доступный ход)?$/, (m, l) => {
    const pieces = { пешка: ['pawn','пішак'], конь:['knight','кінь'], слон:['bishop','слон'], ладья:['rook','тура'], ферзь:['queen','ферзь'], король:['king','король'], дамка:['king','дамка'], шашка:['piece','шашка'] };
    return `${m[1]}, ${side(m[2],l)}, ${pieces[m[3]][l === 'en' ? 0 : 1]}${m[4] ? l === 'en' ? ', legal move' : ', доступний хід' : ''}`;
  }],
  [/^([a-l]\d+), пусто(, доступный ход)?$/, (m,l) => `${m[1]}, ${l === 'en' ? 'empty' : 'порожньо'}${m[2] ? l === 'en' ? ', legal move' : ', доступний хід' : ''}`],
  [/^Аккаунт: (.+)$/, (m,l) => `${l === 'en' ? 'Account' : 'Обліковий запис'}: ${m[1]}`]
];
